    ('ffa3aa46-375b-4fe9-a6a1-153c9bc09c94', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 2 AND code = 'VIE') AND code = 'C5' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'true_false' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'medium' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'create' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Câu ''Em rất yêu quý thầy cô.'' là một câu hỏi. Câu trên đúng hay sai?', 'Cau ''Em rat yeu quy thay co.'' la mot cau hoi. Cau tren dung hay sai?', 'Câu ''Em rất yêu quý thầy cô.'' thể hiện tình cảm biết ơn.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 2']::TEXT[], true, 'approved', 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
