    ('db953a8a-d78a-4dff-83dd-a1b9c092e955', (SELECT id FROM public.topics WHERE subject_id = (SELECT id FROM public.subjects WHERE grade_level_id = 2 AND code = 'VIE') AND code = 'C3' LIMIT 1), (SELECT id FROM public.question_types WHERE code = 'true_false' LIMIT 1), (SELECT id FROM public.difficulty_levels WHERE code = 'hard' LIMIT 1), (SELECT id FROM public.cognitive_levels WHERE code = 'create' LIMIT 1), 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', 'Câu ''Em rất yêu quý thầy cô.'' là một câu hỏi. Theo em, nhận định trên đúng hay sai?', 'Cau ''Em rat yeu quy thay co.'' la mot cau hoi. Theo em, nhan dinh tren dung hay sai?', 'Câu ''Em rất yêu quý thầy cô.'' thể hiện tình cảm biết ơn.', 'Ngân hàng câu hỏi mẫu - sinh tự động', ARRAY['Tiếng Việt','Lớp 2']::TEXT[], true, 'approved', 'a2eb9cd9-2a7b-44da-b94b-f5507afe122f', NOW()),
